ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    content: [
        {"type": "text", text: "Employee onboarding completed successfully!"},
        {"type": "text", text: "Results:\n" ++ write(payload, "application/json")}
    ],
    isError: false
}

%dw 2.0
output application/json
---
{
    content: [
        {"type": "text", text: "Onboarding Status:"},
        {"type": "text", text: write(payload, "application/json")}
    ],
    isError: false
}

mcp:tool-listener.mcp:parameters-schema:
{
                "type": "object",
                "properties": {
                    "employeeId": {"type": "string", "description": "Unique employee identifier"},
                    "step": {"type": "string", "enum": ["profile-creation", "asset-allocation", "welcome-email", "asset-notification", "onboarding-complete"], "description": "The specific onboarding step to retry"}
                },
                "required": ["employeeId", "step"]
            }

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    content: [
        {"type": "text", text: "Step retry initiated successfully!"},
        {"type": "text", text: write(payload, "application/json")}
    ],
    isError: false
}

%dw 2.0
output application/json
---
{
    content: [
        {"type": "text", text: "System Health:"},
        {"type": "text", text: write(payload, "application/json")}
    ],
    isError: false
}

mcp:tool-listener.mcp:parameters-schema:
{
                "type": "object",
                "properties": {
                    "prompt": {"type": "string", "minLength": 10, "maxLength": 1000, "description": "Natural language request for employee onboarding assistance"},
                    "context": {
                        "type": "object",
                        "properties": {
                            "employeeId": {"type": "string"},
                            "department": {"type": "string"},
                            "currentStep": {"type": "string"}
                        },
                        "description": "Optional context to help with reasoning"
                    }
                },
                "required": ["prompt"]
            }

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    content: [
        {"type": "text", text: "AI Reasoning:"},
        {"type": "text", text: write(payload, "application/json")}
    ],
    isError: false
}
